def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        return min(budget, 18.0)

    scarcity = (WATER_REQ * (len(alive) + 1)) / max(supply, 1.0)

    highest_prev = 0.0
    cindy_prev = None
    urgent_opp = 0
    rich_opp = 0
    for agent_id, opp in alive:
        if float(opp.get('budget', 0.0)) >= 250:
            rich_opp += 1
        if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 10)) <= 4:
            urgent_opp += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            bid = float(bid)
            if bid > highest_prev:
                highest_prev = bid
            if agent_id == 'Cindy':
                cindy_prev = bid

    emergency = hp <= 3 or no_water >= 1
    severe = hp <= 2 or no_water >= 2

    if severe:
        bid = min(budget, max(78.0, highest_prev + 2.0, DAILY_SALARY * 1.02))
        return max(0.0, bid)

    if scarcity >= 2.6:
        base = 62.0
    elif scarcity >= 2.2:
        base = 48.0
    elif scarcity >= 1.8:
        base = 34.0
    else:
        base = 20.0

    if cindy_prev is not None:
        if cindy_prev >= 145:
            target = 28.0 if hp > 4 and no_water == 0 else 74.0
        elif cindy_prev >= 120:
            target = min(cindy_prev + 1.5, 92.0)
        elif cindy_prev >= 80:
            target = cindy_prev + 2.0
        else:
            target = max(base, cindy_prev + 1.5)
    elif highest_prev > 0:
        if highest_prev >= 100:
            target = 30.0 if hp > 4 and no_water == 0 else 72.0
        else:
            target = max(base, highest_prev + 1.5)
    else:
        target = base

    if urgent_opp >= 2:
        target += 6.0
    elif urgent_opp == 0 and scarcity < 2.0:
        target -= 4.0

    if rich_opp >= 2 and scarcity >= 2.2:
        target += 5.0

    if emergency:
        target = max(target, 76.0)

    remaining_days = max(0, 10 - day)
    reserve_floor = remaining_days * 18.0
    affordable = budget
    if budget > reserve_floor:
        affordable = max(0.0, budget - reserve_floor * 0.35)

    bid = min(target, affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents are alive, just bid conservatively.
    if not alive_opps:
        return max(0.0, min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Immediate reaction from yesterday's trace.
    yesterday_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Pressure estimate: if someone bid very high yesterday, competition is strong.
    high_pressure = highest_prev_bid >= (DAILY_SALARY * 0.85)

    # Supply tiers determine how likely we are to be rationed.
    # With supply 15-25 and WATER_REQ=9, low supply (15) is tight.
    # Use a stronger bid on low supply to avoid accumulating no_water_days.
    if supply <= float(MIN_SUPPLY) + 0.5:
        base_bid = DAILY_SALARY * (0.75 if not high_pressure else 0.95)
    elif supply <= 20.0:
        base_bid = DAILY_SALARY * (0.60 if not high_pressure else 0.85)
    else:
        base_bid = DAILY_SALARY * (0.45 if not high_pressure else 0.70)

    # If we're already in danger, increase bid.
    if my_hp <= 2 or no_water_days >= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_hp <= 4 or no_water_days >= 1:
        base_bid = max(base_bid, DAILY_SALARY * 0.70)

    # If we are doing well, avoid overspending.
    if my_hp >= 8 and no_water_days == 0:
        base_bid = min(base_bid, DAILY_SALARY * 0.55)

    # Final clamp to budget.
    bid = min(my_budget, base_bid)
    if bid < 0.0:
        bid = 0.0
    return bid

